-- ATLAS Core Private Beta v0.2.3
begin;create extension if not exists pgcrypto;
create or replace function public.set_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
create or replace function public.try_uuid(v text) returns uuid language plpgsql immutable as $$begin return v::uuid;exception when invalid_text_representation then return null;end$$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.organizations(id uuid primary key default gen_random_uuid(),name text not null,legal_name text,industry text,active boolean default true,created_by uuid references auth.users(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.organization_members(org_id uuid references public.organizations(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,role text not null default 'staff' check(role in('owner','admin','accountant','manager','staff','viewer')),status text default 'active',created_at timestamptz default now(),updated_at timestamptz default now(),primary key(org_id,user_id));
create table if not exists public.organization_settings(org_id uuid primary key references public.organizations(id) on delete cascade,settings jsonb default '{}'::jsonb,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.organization_modules(org_id uuid references public.organizations(id) on delete cascade,module_code text,enabled boolean default false,launch_status text default 'coming_soon',created_at timestamptz default now(),updated_at timestamptz default now(),primary key(org_id,module_code));
create table if not exists public.customers(id uuid primary key default gen_random_uuid(),org_id uuid references public.organizations(id) on delete cascade,name text not null,email text,phone text,status text default 'active',created_by uuid default auth.uid(),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.vendors(id uuid primary key default gen_random_uuid(),org_id uuid references public.organizations(id) on delete cascade,name text not null,email text,phone text,status text default 'active',created_by uuid default auth.uid(),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),org_id uuid references public.organizations(id) on delete cascade,sku text not null,name text not null,quantity numeric default 0,reorder_point numeric default 0,unit_cost numeric default 0,unit_price numeric default 0,status text default 'active',created_by uuid default auth.uid(),created_at timestamptz default now(),updated_at timestamptz default now(),unique(org_id,sku));
create table if not exists public.invoices(id uuid primary key default gen_random_uuid(),org_id uuid references public.organizations(id) on delete cascade,customer_id uuid references public.customers(id),invoice_number text not null,issue_date date default current_date,due_date date,total numeric default 0,balance_due numeric default 0,status text default 'draft',created_by uuid default auth.uid(),created_at timestamptz default now(),updated_at timestamptz default now(),unique(org_id,invoice_number));
create table if not exists public.invoice_lines(id uuid primary key default gen_random_uuid(),org_id uuid references public.organizations(id) on delete cascade,invoice_id uuid references public.invoices(id) on delete cascade,product_id uuid references public.products(id),description text not null,quantity numeric default 1,unit_price numeric default 0,tax_rate numeric default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),org_id uuid references public.organizations(id) on delete cascade,invoice_id uuid references public.invoices(id),amount numeric not null check(amount>0),payment_date date default current_date,status text default 'confirmed',created_by uuid default auth.uid(),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.expense_categories(id uuid primary key default gen_random_uuid(),org_id uuid references public.organizations(id) on delete cascade,name text not null,created_at timestamptz default now(),updated_at timestamptz default now(),unique(org_id,name));
create table if not exists public.expenses(id uuid primary key default gen_random_uuid(),org_id uuid references public.organizations(id) on delete cascade,vendor_id uuid references public.vendors(id),category_id uuid references public.expense_categories(id),description text not null,amount numeric not null,expense_date date default current_date,status text default 'pending',created_by uuid default auth.uid(),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.chart_of_accounts(id uuid primary key default gen_random_uuid(),org_id uuid references public.organizations(id) on delete cascade,account_number text not null,name text not null,account_type text not null,created_at timestamptz default now(),updated_at timestamptz default now(),unique(org_id,account_number));
create table if not exists public.journal_entries(id uuid primary key default gen_random_uuid(),org_id uuid references public.organizations(id) on delete cascade,entry_number text not null,entry_date date default current_date,memo text,status text default 'draft',created_by uuid default auth.uid(),created_at timestamptz default now(),updated_at timestamptz default now(),unique(org_id,entry_number));
create table if not exists public.journal_lines(id uuid primary key default gen_random_uuid(),org_id uuid references public.organizations(id) on delete cascade,journal_entry_id uuid references public.journal_entries(id) on delete cascade,account_id uuid references public.chart_of_accounts(id),debit numeric default 0,credit numeric default 0,created_at timestamptz default now(),check(debit>=0 and credit>=0 and not(debit>0 and credit>0)));
create table if not exists public.employees(id uuid primary key default gen_random_uuid(),org_id uuid references public.organizations(id) on delete cascade,user_id uuid references auth.users(id),full_name text not null,department text,job_title text,status text default 'active',created_by uuid default auth.uid(),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.documents(id uuid primary key default gen_random_uuid(),org_id uuid references public.organizations(id) on delete cascade,file_name text not null,storage_path text not null,classification text default 'internal',uploaded_by uuid default auth.uid(),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.audit_logs(id bigint generated always as identity primary key,org_id uuid references public.organizations(id) on delete cascade,user_id uuid references auth.users(id),action text not null,table_name text,record_id text,old_data jsonb,new_data jsonb,created_at timestamptz default now());
create or replace function public.is_org_member(o uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from organization_members where org_id=o and user_id=auth.uid() and status='active')$$;
create or replace function public.has_org_role(o uuid,r text[]) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from organization_members where org_id=o and user_id=auth.uid() and status='active' and role=any(r))$$;
create or replace function public.can_write_business_data(o uuid) returns boolean language sql stable as $$select public.has_org_role(o,array['owner','admin','accountant','manager','staff'])$$;
create or replace function public.can_write_accounting_data(o uuid) returns boolean language sql stable as $$select public.has_org_role(o,array['owner','admin','accountant'])$$;
create or replace function public.can_manage_people(o uuid) returns boolean language sql stable as $$select public.has_org_role(o,array['owner','admin','manager'])$$;
create or replace function public.validate_journal_entry(j uuid) returns boolean language sql stable security definer set search_path=public as $$select coalesce(sum(debit),0)=coalesce(sum(credit),0) and coalesce(sum(debit),0)>0 from journal_lines where journal_entry_id=j$$;
create or replace function public.create_organization(organization_name text,organization_legal_name text default null,organization_industry text default null) returns uuid language plpgsql security definer set search_path=public as $$declare o uuid;begin if auth.uid() is null then raise exception 'Authentication required';end if;insert into organizations(name,legal_name,industry,created_by) values(organization_name,organization_legal_name,organization_industry,auth.uid()) returning id into o;insert into organization_members values(o,auth.uid(),'owner','active',now(),now());insert into organization_settings(org_id) values(o);insert into organization_modules(org_id,module_code,enabled,launch_status) values(o,'core',true,'active'),(o,'crm',true,'beta'),(o,'accounting',true,'beta'),(o,'inventory',true,'beta'),(o,'hr',true,'beta');insert into chart_of_accounts(org_id,account_number,name,account_type) values(o,'1000','Cash','asset'),(o,'1100','Accounts Receivable','asset'),(o,'2000','Accounts Payable','liability'),(o,'4000','Revenue','revenue'),(o,'5000','Expenses','expense');return o;end$$;
alter table public.profiles enable row level security;alter table public.organizations enable row level security;alter table public.organization_members enable row level security;alter table public.organization_settings enable row level security;alter table public.organization_modules enable row level security;alter table public.customers enable row level security;alter table public.vendors enable row level security;alter table public.products enable row level security;alter table public.invoices enable row level security;alter table public.invoice_lines enable row level security;alter table public.payments enable row level security;alter table public.expense_categories enable row level security;alter table public.expenses enable row level security;alter table public.chart_of_accounts enable row level security;alter table public.journal_entries enable row level security;alter table public.journal_lines enable row level security;alter table public.employees enable row level security;alter table public.documents enable row level security;alter table public.audit_logs enable row level security;
create policy profiles_self on public.profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid());create policy org_read on public.organizations for select to authenticated using(public.is_org_member(id));create policy org_create on public.organizations for insert to authenticated with check(created_by=auth.uid());create policy org_update on public.organizations for update to authenticated using(public.has_org_role(id,array['owner','admin']));create policy member_read on public.organization_members for select to authenticated using(public.is_org_member(org_id));create policy member_manage on public.organization_members for all to authenticated using(public.has_org_role(org_id,array['owner','admin'])) with check(public.has_org_role(org_id,array['owner','admin']));
create policy settings_access on public.organization_settings for all to authenticated using(public.is_org_member(org_id)) with check(public.has_org_role(org_id,array['owner','admin']));create policy modules_access on public.organization_modules for all to authenticated using(public.is_org_member(org_id)) with check(public.has_org_role(org_id,array['owner','admin']));
create policy customers_access on public.customers for all to authenticated using(public.is_org_member(org_id)) with check(public.can_write_business_data(org_id));create policy vendors_access on public.vendors for all to authenticated using(public.is_org_member(org_id)) with check(public.can_write_business_data(org_id));create policy products_access on public.products for all to authenticated using(public.is_org_member(org_id)) with check(public.can_write_business_data(org_id));create policy invoices_access on public.invoices for all to authenticated using(public.is_org_member(org_id)) with check(public.can_write_business_data(org_id));create policy invoice_lines_access on public.invoice_lines for all to authenticated using(public.is_org_member(org_id)) with check(public.can_write_business_data(org_id));create policy payments_access on public.payments for all to authenticated using(public.is_org_member(org_id)) with check(public.can_write_accounting_data(org_id));create policy categories_access on public.expense_categories for all to authenticated using(public.is_org_member(org_id)) with check(public.can_write_accounting_data(org_id));create policy expenses_access on public.expenses for all to authenticated using(public.is_org_member(org_id)) with check(public.can_write_business_data(org_id));create policy accounts_access on public.chart_of_accounts for all to authenticated using(public.is_org_member(org_id)) with check(public.can_write_accounting_data(org_id));create policy journals_access on public.journal_entries for all to authenticated using(public.is_org_member(org_id)) with check(public.can_write_accounting_data(org_id));create policy lines_access on public.journal_lines for all to authenticated using(public.is_org_member(org_id)) with check(public.can_write_accounting_data(org_id));create policy employees_access on public.employees for all to authenticated using(public.can_manage_people(org_id) or user_id=auth.uid()) with check(public.can_manage_people(org_id));create policy documents_access on public.documents for all to authenticated using(public.is_org_member(org_id)) with check(public.can_write_business_data(org_id));create policy audit_read on public.audit_logs for select to authenticated using(public.has_org_role(org_id,array['owner','admin','accountant']));
grant usage on schema public to authenticated;grant select,insert,update,delete on all tables in schema public to authenticated;grant usage,select on all sequences in schema public to authenticated;revoke insert,update,delete on public.audit_logs from authenticated;grant execute on function public.is_org_member(uuid),public.has_org_role(uuid,text[]),public.can_write_business_data(uuid),public.can_write_accounting_data(uuid),public.can_manage_people(uuid),public.create_organization(text,text,text),public.try_uuid(text) to authenticated;commit;